function show(html:string,type='dialog'){keys.clear();mouseDown=false;if(started)updateHUD();modal=type;$('modal-content').innerHTML=html;$('modal').classList.remove('hidden');$('cursor').classList.add('hidden');document.body.classList.remove('playing');$('modal-close').focus();}
function close(){if(dead)return;modal='';$('modal').classList.add('hidden');if(started){$('cursor').classList.remove('hidden');document.body.classList.add('playing');updateHUD();}}
function on(id:string,fn:()=>void){$(id)?.addEventListener('click',()=>{sound.ui();fn();});}
function speaker(q:Quest){return q.id==='M05'&&save.route==='sorel'?'Sorel':q.speaker;}
function giver(q:Quest){return q.id==='M05'&&save.route==='sorel'?'sorel':q.giver;}
function briefing(q:Quest){
 if(save.active){toast('Une séquence est déjà active','Termine-la ou abandonne-la depuis le journal.');return;}
 show(`<div class="dialog-portrait">${speaker(q)[0]}</div><div class="dialog-speaker">${speaker(q)}</div><div class="dialog-role">${q.role}</div><div class="dialog-body"><span class="tag">${q.id} / ${q.district}</span><h2>${q.title}</h2><p>${q.id==='M05'&&save.route==='sorel'?q.briefing.replace('Notre galerie rejoint une annexe ; le badge de Sorel ouvre le vestibule.','Mon badge ouvre le vestibule. La galerie communautaire reste fermée tant que le registre est sous contrôle.'):q.briefing}</p><p class="muted">${q.approaches}</p><button class="primary" id="accept">Accepter <b>${q.reward} ₡</b></button><button class="secondary" id="decline">Continuer à explorer</button></div>`);
 on('decline',close);on('accept',()=>{save=acceptQuest(save,q.id);operation=null;if(q.id==='M02'){physics.teleport(archiveAgent.body,LOC.archiveAgent);archiveAgent.index=0;}persist();close();toast(q.title,'Point de reprise enregistré au briefing.');});
}
function contact(id:string){
 const info=contactInfo[id];const next=nextMain(save),offers=QUESTS.filter(q=>available(q,save)&&!q.common&&giver(q)===id&&(q.id[0]!=='M'||q===next));
 const endingText=save.ending=== 'publish'?'Les relais indépendants délivrent les autorisations.':'La purge est annulée ; les services ont rouvert.';
 const words=id==='garage'?(save.completed.includes('M01')?'« La grille verte est ouverte. Les ateliers restent un relais. Regarde le journal si tu cherches une autre course. »':'« Sous les voies. La grille verte, côté ateliers. Je te laisse toujours une sortie. »'):id==='nadia'?(save.ending?`« ${endingText} Il reste des gens à aider. »`:'« Qui pourra encore entrer chez lui demain ? »'):id==='lise'?(save.nightChoice==='destroy'?'« Les dossiers privés n’existent plus. La permanence reste ouverte. »':save.nightChoice==='entrust'?'« Les preuves sont en sûreté ici. Nous choisirons qui peut les voir. »':'« L’entraide n’oblige personne à livrer sa vie privée. »'):save.ending?`« ${endingText} »`:'« Il faut distinguer ce que l’on sait de ce que l’on peut prouver. »';
 show(`<div class="dialog-portrait">${info.name[0]}</div><div class="dialog-speaker">${info.name}</div><div class="dialog-role">${info.role}</div><div class="dialog-body"><p>${words}</p>${offers.map(q=>`<button class="secondary" id="offer-${q.id}">${q.id} · ${q.title}<small>${q.reward} ₡ · ${q.district}</small></button>`).join('')}${id==='garage'?'<button class="secondary" id="equip">Choisir mes deux implants</button><button class="secondary" id="service">Soins et réparation · gratuit</button><button class="secondary" id="garage-fleet">Mes véhicules</button><button class="secondary" id="rest">Attendre une autre heure</button>':''}<button id="leave" class="primary">Repartir</button></div>`);
 offers.forEach(q=>on('offer-'+q.id,()=>briefing(q)));on('leave',close);on('equip',loadout);on('garage-fleet',()=>garageFleet(LOC.garage));on('service',()=>{health=100;repairCar(car);close();toast('Prêt à repartir','Soins et carrosserie restaurés. Les cartouches s’achètent à l’armurerie.','success');});on('rest',()=>{show('<span class="tag">GARAGE DE MINA</span><h2>La ville change d’heure.</h2><p>Les trajets et les occupations suivent les horaires des ateliers, commerces, bureaux et terrasses.</p><button class="secondary" id="morning">Attendre le matin · 08 h 00</button><button class="secondary" id="day">Attendre la journée · 14 h 00</button><button class="secondary" id="evening">Attendre la soirée · 21 h 30</button>');for(const[id,hour]of [['morning',8],['day',14],['evening',21.5]]as const)on(id,()=>{save.hour=hour;persist();close();toast('Une autre heure dans la ville',periodAt(hour));});});
}
function syncAmmo(){const w=currentWeapon();ammo=save.inventory.magazines[w.id];reserve=save.inventory.ammo[w.ammo];}
function equipWeapon(id:WeaponId){if(!save.inventory.weapons.includes(id)){toast('Arme non possédée','L’armurerie Traverse se trouve à l’est du garage.');return;}save.inventory.equipped=id;reloadAt=0;reloadId=null;syncAmmo();persist();toast(WEAPONS[id].name,'Chargeur '+ammo+' · Réserve '+reserve+' '+AMMUNITION[WEAPONS[id].ammo].name);}
