 const apply=()=>{view.effects.enabled=settings.effects;grade.enabled=settings.effects;renderer.domElement.style.filter=settings.grayscale?'grayscale(1)':'';try{localStorage.setItem('deadline.settings',JSON.stringify(settings));}catch{}sound.setVolume(settings.volume);renderer.shadowMap.enabled=settings.quality==='high';renderer.setPixelRatio(Math.min(devicePixelRatio,settings.quality==='high'?1.5:1));bloom.enabled=settings.quality==='high';resize();$('fps').classList.toggle('hidden',!settings.fps);};
